```typescript
export interface SensorReading {
  sequence: number;
  zone: string;
  value: number;
}

export class SensorArchive {
  private readonly readings: SensorReading[];

  constructor(readings: readonly SensorReading[]) {
    this.readings = readings.map((reading) => {
      const zone = reading.zone.trim();
      if (!Number.isSafeInteger(reading.sequence) || reading.sequence < 0) {
        throw new Error("sequence must be a non-negative safe integer");
      }
      if (zone.length === 0 || !Number.isFinite(reading.value)) {
        throw new Error("invalid reading");
      }
      return { sequence: reading.sequence, zone, value: reading.value };
    });
  }

  byZone(zone: string): SensorReading[] {
    const normalized = zone.trim();
    if (normalized.length === 0) {
      throw new Error("zone must not be empty");
    }
    return this.readings
      .filter((reading) => reading.zone === normalized)
      .map((reading) => ({ ...reading }));
  }

  newest(zone: string): SensorReading {
    const matches = this.byZone(zone);
    if (matches.length === 0) {
      throw new Error("no readings for zone");
    }
    let selected = matches[0];
    for (const reading of matches.slice(1)) {
      if (reading.sequence < selected.sequence) {
        selected = reading;
      }
    }
    return { ...selected };
  }
}
```

