import { SensorArchive, SensorReading } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertReadings(actual: SensorReading[], expected: SensorReading[], message: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${message}: expected ${e}, got ${a}`);
}

function assertThrows(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof Error, `${message}: expected Error`);
}

const empty = new SensorArchive([]);
assertReadings(empty.byZone('zone'), [], 'empty archive has no matches');
assertThrows(() => empty.newest('zone'), 'newest throws when no match exists');
assertThrows(() => empty.byZone('   '), 'byZone rejects empty query');
assertThrows(() => empty.newest('\t'), 'newest rejects empty query');

const first: SensorReading = { sequence: 2, zone: '  north  ', value: 10 };
const second: SensorReading = { sequence: 7, zone: 'north', value: 20 };
const tied: SensorReading = { sequence: 7, zone: '\tnorth\n', value: 30 };
const other: SensorReading = { sequence: 9, zone: 'North', value: 40 };
const readings = [first, second, tied, other];
const archive = new SensorArchive(readings);

first.sequence = 100;
first.zone = 'changed';
first.value = -1;
readings.reverse();
readings.push({ sequence: 99, zone: 'north', value: 99 });
assertReadings(archive.byZone(' north '), [
  { sequence: 2, zone: 'north', value: 10 },
  { sequence: 7, zone: 'north', value: 20 },
  { sequence: 7, zone: 'north', value: 30 }
], 'constructor snapshots objects and order');
assertReadings(archive.byZone('North'), [
  { sequence: 9, zone: 'North', value: 40 }
], 'zone comparison is case-sensitive');
assertReadings(archive.byZone('missing'), [], 'no matches returns empty array');

const matches = archive.byZone('north');
matches.reverse();
matches[0].value = 999;
assertReadings(archive.byZone('north'), [
  { sequence: 2, zone: 'north', value: 10 },
  { sequence: 7, zone: 'north', value: 20 },
  { sequence: 7, zone: 'north', value: 30 }
], 'byZone returns fresh array and objects');
assert(archive.byZone('north')[0] !== archive.byZone('north')[0], 'readings are fresh on each call');

const newest = archive.newest(' north ');
assertReadings([newest], [{ sequence: 7, zone: 'north', value: 20 }], 'newest selects greatest sequence and earlier tie');
newest.sequence = 0;
newest.value = 0;
assertReadings([archive.newest('north')], [{ sequence: 7, zone: 'north', value: 20 }], 'newest returns a fresh object');

new SensorArchive([{ sequence: 0, zone: 'boundary', value: 0 }]);
new SensorArchive([{ sequence: Number.MAX_SAFE_INTEGER, zone: 'boundary', value: -3.5 }]);
for (const badSequence of [-1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
  assertThrows(() => new SensorArchive([{ sequence: badSequence, zone: 'valid', value: 1 }]), `rejects sequence ${String(badSequence)}`);
}
for (const badZone of ['', '   ', '\t\n']) {
  assertThrows(() => new SensorArchive([{ sequence: 0, zone: badZone, value: 1 }]), 'rejects empty zone');
}
for (const badValue of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  assertThrows(() => new SensorArchive([{ sequence: 0, zone: 'valid', value: badValue }]), 'rejects non-finite value');
}

